    niko_label.text = "Niko Kadi!"

func on_player_drew(player: int) -> void:
    GameState.announced_kadi[player] = false

func reset_announcements() -> void:
    for i in range(GameState.announced_kadi.size()):
        GameState.announced_kadi[i] = false
    niko_label.text = ""

